import subprocess, string
def run(args):
    try:
        p=subprocess.run(["./executable"]+args, capture_output=True, text=True, timeout=3)
        return p.returncode, p.stdout, p.stderr
    except Exception as e:
        return None,str(e),""
for ch in string.ascii_letters+string.digits:
    rc,out,err=run([f"-{ch}"])
    # summarise first line
    print(ch, rc, repr((out+err)[:300].replace("\n"," | ")))
PY"}

