def parse_bool(value):
    if value is None:
        return True
    if value == "":
        return True
    c = value[0]
    if c.isdigit():
        # leading integer
        i = 0
        n = 0
        while i < len(value) and value[i].isdigit():
            n = n * 10 + int(value[i])
