    if s is None:
        return 0
    i = 0
    while i < len(s) and s[i] in " \t\r\n":
        i += 1
    sign = 1
    if i < len(s) and s[i] in "+-":
        if s[i] == "-":
            sign = -1
        i += 1
    n = 0
    seen = False
    while i < len(s) and s[i].isdigit():
