    if parts is None:
        # maybe continuous 12 hex digits
        if len(s) == 12 and all(c in "0123456789abcdefABCDEF" for c in s):
            return [int(s[i:i+2], 16) for i in range(0, 12, 2)]
        return None
    # dot form could be 3 groups of 4 hexdigits
    if len(parts) == 3 and all(len(p) == 4 for p in parts):
        try:
            out = []
            for p in parts:
                v = int(p, 16)
                out.append((v >> 8) & 0xFF)
                out.append(v & 0xFF)
            return out
        except Exception:
            return None
    if len(parts) != 6:
        return None
    out = []
    for p in parts:
        if p == "" or len(p) > 2:
            return None
        try:
            out.append(int(p, 16))
        except Exception:
            return None
    return out

def format_mac(mac):
    return "-".join(f"{b:02x}" for b in mac)

# Range list implementation (list of [begin,end] sorted, merged)
class RangeList:
    def __init__(self):
        self.ranges = []  # list of [begin,end]

    def add(self, begin, end):
        if begin is None or end is None:
            return
        if begin > end:
            return
        self.ranges.append([begin, end])
        self._merge()

    def _merge(self):
        if not self.ranges:
            return
        r = sorted(self.ranges)
        merged = [list(r[0])]
        for b, e in r[1:]:
            last = merged[-1]
            if b <= last[1] + 1:
                if e > last[1]:
                    last[1] = e
            else:
                merged.append([b, e])
        self.ranges = merged

    def remove(self, other):
        # other: RangeList
        if not other.ranges or not self.ranges:
            return
        new_ranges = []
        for b, e in self.ranges:
            cur = [(b, e)]
            for ob, oe in other.ranges:
                nxt = []
                for cb, ce in cur:
                    if oe < cb or ob > ce:
                        nxt.append((cb, ce))
                    else:
                        if ob > cb:
                            nxt.append((cb, ob - 1))
                        if oe < ce:
                            nxt.append((oe + 1, ce))
                cur = nxt
                if not cur:
                    break
            new_ranges.extend([list(x) for x in cur])
        self.ranges = new_ranges

    def count_total(self):
        return sum(e - b + 1 for b, e in self.ranges)

    def __bool__(self):
        return bool(self.ranges)

    def pick(self, index):
        """return element number index (0-based) in sorted ranges, or None"""
        for b, e in self.ranges:
            sz = e - b + 1
            if index < sz:
                return b + index
            index -= sz
        return None

# IPv4/IPv6 parsing and formatting

def parse_ipv4_token(s, pos=0):
    """Parse dotted quad at s[pos:], return (value, next_pos) or (None,pos)."""
    parts = []
    i = pos
    for part_idx in range(4):
        if i >= len(s) or not s[i].isdigit():
            return None, pos
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        num_s = s[i:j]
        # original rejects overly large? digits parsed as decimal
        try:
            v = int(num_s, 10)
        except Exception:
            return None, pos
        if v > 255:
            return None, pos
        parts.append(v)
        i = j
        if part_idx < 3:
            if i >= len(s) or s[i] != '.':
                return None, pos
            i += 1
    val = (parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]
    return val, i

def format_ipv4(v):
    return f"{(v>>24)&255}.{(v>>16)&255}.{(v>>8)&255}.{v&255}"

def parse_ipv6_token(s, pos=0):
    """Parse IPv6 (without embedded IPv4) at pos. Return (value, next_pos) or (None,pos)."""
    i = pos
    start = i
    # find end of token: hex digits and colons only; stop at other chars
    j = i
    while j < len(s) and (s[j] in "0123456789abcdefABCDEF:"):
        j += 1
    token = s[i:j]
    if token == "" or ":" not in token:
        return None, pos
    # Validate and parse manually
    # Reject ::: etc and single trailing/leading colon unless ::
    if token.count("::") > 1:
        return None, pos
    if "::" in token:
        left_s, right_s = token.split("::", 1)
        left = [] if left_s == "" else left_s.split(":")
        right = [] if right_s == "" else right_s.split(":")
        if any(g == "" for g in left + right):
            return None, pos
        if len(left) + len(right) > 7:
            return None, pos
        groups = []
        try:
            for g in left:
                if len(g) > 4:
                    return None, pos
                groups.append(int(g, 16))
            missing = 8 - len(left) - len(right)
            groups.extend([0] * missing)
            for g in right:
                if len(g) > 4:
                    return None, pos
                groups.append(int(g, 16))
        except Exception:
            return None, pos
    else:
        parts = token.split(":")
        if len(parts) != 8:
            return None, pos
        groups = []
        try:
            for g in parts:
                if g == "" or len(g) > 4:
                    return None, pos
                groups.append(int(g, 16))
        except Exception:
            return None, pos
    if len(groups) != 8:
        return None, pos
    val = 0
    for g in groups:
        if g < 0 or g > 0xFFFF:
            return None, pos
        val = (val << 16) | g
    return val, j

def format_ipv6(v):
    groups = [(v >> (16 * (7 - i))) & 0xFFFF for i in range(8)]
    # find longest run of zeros with length >=2; if tie, first
    best_start = -1
    best_len = 0
    cur_start = -1
    cur_len = 0
    for i, g in enumerate(groups):
        if g == 0:
            if cur_start == -1:
                cur_start = i
                cur_len = 1
            else:
                cur_len += 1
            if cur_len > best_len:
                best_len = cur_len
                best_start = cur_start
        else:
            cur_start = -1
            cur_len = 0
    if best_len < 2:
        return ":".join(f"{g:x}" for g in groups)
    left = groups[:best_start]
    right = groups[best_start + best_len:]
    left_s = ":".join(f"{g:x}" for g in left)
    right_s = ":".join(f"{g:x}" for g in right)
    return f"{left_s}::{right_s}"

def format_ip(version, v):
    return format_ipv4(v) if version == 4 else format_ipv6(v)

def parse_range_item(token):
    """Parse one range item (no commas) -> (version, begin, end) or None.
    Token is stripped of surrounding whitespace (? original allows trailing space)."""
    s = token
    # original trims trailing whitespace? bare "10.0.0.1 " worked; leading space
    # was rejected at bare-arg level, but for --range values leading space may
    # be skipped by file parsers. We'll strip both for value case; bare-arg
    # classification handles leading-space rejection before calling this.
    # However there are nuances like order of calls, keep stripping.
    s_stripped = s.strip()
    if s_stripped == "":
        return None
    s = s_stripped
    # Determine version by presence of ':' vs '.'. IPv4 contains '.', IPv6 ':'
    # Try IPv6 first if ':' present and no '.' before??? embedded v4 not supported.
    if ":" in s:
        val, nxt = parse_ipv6_token(s, 0)
        if val is None:
            return None
        version = 6
        begin = val
        i = nxt
    else:
        val, nxt = parse_ipv4_token(s, 0)
        if val is None:
            return None
        version = 4
        begin = val
        i = nxt
    maxbits = 32 if version == 4 else 128
    # skip spaces?
    while i < len(s) and s[i] in " \t":
        i += 1
    if i >= len(s):
        return (version, begin, begin)
    if s[i] == '/':
        i += 1
        # prefix digits; empty -> 0 (observed)
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        if j == i:
            prefix = 0
        else:
            try:
                prefix = int(s[i:j], 10)
            except Exception:
                return None
        i = j
        # trailing junk after prefix? original: need check; treat spaces/end only
        while i < len(s) and s[i] in " \t":
            i += 1
        if i < len(s):
            return None
        if prefix < 0 or prefix > maxbits:
            return None
        if prefix == maxbits:
            return (version, begin, begin)
        hostbits = maxbits - prefix
        size = 1 << hostbits
        network = (begin >> hostbits) << hostbits
        return (version, network, network + size - 1)
    elif s[i] == '-':
        i += 1
        while i < len(s) and s[i] in " \t":
            i += 1
        if version == 4:
            val2, nxt2 = parse_ipv4_token(s, i)
        else:
            val2, nxt2 = parse_ipv6_token(s, i)
        if val2 is None:
            return None
        i = nxt2
        while i < len(s) and s[i] in " \t":
            i += 1
        if i < len(s):
            return None
        return (version, begin, val2)
    else:
        # trailing junk e.g. "10.0.0.1abc" - original bad
        return None

def format_range(version, begin, end):
    if begin == end:
        return format_ip(version, begin)
    size = end - begin + 1
    maxbits = 32 if version == 4 else 128
    # check power of two and alignment
    if size > 0 and (size & (size - 1)) == 0:
        hostbits = size.bit_length() - 1
        if hostbits <= maxbits and (begin & (size - 1)) == 0:
            prefix = maxbits - hostbits
            return f"{format_ip(version, begin)}/{prefix}"
    return f"{format_ip(version, begin)}-{format_ip(version, end)}"

