    if value == "":
        return
    # split on ','
    tokens = value.split(",")
    for tok in tokens:
        if tok == "":
            continue
        low = tok.lower()
        # token must be non-empty prefix of open/closed/all (case-insensitive)
        if "open".startswith(low) and low != "":
            cfg.output_status_open = True
        elif "closed".startswith(low) and low != "":
            cfg.output_status_closed = True
        elif "all".startswith(low) and low != "":
            cfg.output_status_open = True
            cfg.output_status_closed = True
        else:
            eprint(f"FAIL: unknown 'show' spec: {tok}")
            raise FatalExit(1)

