def read_config_file(cfg, filename, silent_missing=False):
    """Read a masscan config file. filename may be None (from missing -c arg)."""
    if filename is None:
        eprint("[-] FAIL: reading configuration file")
        eprint("[-] (null): Bad address")
        try:
            cwd = os.getcwd()
        except Exception:
            cwd = ""
        eprint(f"[-] cwd = {cwd}")
        return False
    try:
        with open(filename, "r", errors="ignore") as f:
            lines = f.read().splitlines()
    except OSError as ex:
        if silent_missing:
            return False
        eprint("[-] FAIL: reading configuration file")
        eprint(f"[-] {filename}: {ex.strerror or str(ex)}")
        try:
            cwd = os.getcwd()
        except Exception:
            cwd = ""
        eprint(f"[-] cwd = {cwd}")
        return False
    for line in lines:
        # Config grammar observed: leading spaces ok; first char must be alnum
        # otherwise line ignored (comments, punctuation). Name chars alnum,-,_
        # then optional spaces, '=', optional spaces, value=rest (trim trailing ws/CR)
        s = line.lstrip(" \t")
        if not s:
            continue
        if not (s[0].isalnum()):
            continue
        i = 0
        while i < len(s) and (s[i].isalnum() or s[i] in "-_"):
            i += 1
        if i == 0:
            continue
        name = s[:i]
        j = i
        while j < len(s) and s[j] in " \t":
            j += 1
        if j >= len(s) or s[j] != '=':
            continue
        j += 1
        while j < len(s) and s[j] in " \t":
            j += 1
        value = s[j:].rstrip(" \t\r")
        set_parameter(cfg, name, value)
    return True

def load_pcap_payloads(cfg, filename):
    cfg.pcap_payloads_filename = filename
    # Attempt to read pcap file and extract payloads (best effort, mirrors errors)
    try:
        with open(filename, "rb") as f:
            data = f.read()
    except OSError as ex:
        # Original messages (without [-] prefix on first two lines)
        eprint(f"{filename}: could not open capture file")
        eprint(f"{filename}: {ex.strerror or str(ex)}")
        eprint(f"payloads: can't read from file '{filename}'")
        return
    if len(data) < 24:
        eprint(f"{filename}: No such file or directory")
        eprint(f"payloads: can't read from file '{filename}'")
        return
    # parse pcap (both endians based on magic)
    magic = data[:4]
    if magic == b'\xd4\xc3\xb2\xa1':
        endian = '<'
    elif magic == b'\xa1\xb2\xc3\xd4':
        endian = '>'
    else:
        # treat as could not open?
        eprint(f"{filename}: No such file or directory")
        eprint(f"payloads: can't read from file '{filename}'")
        return
    off = 24
    while off + 16 <= len(data):
        try:
            ts_sec, ts_usec, incl, orig = struct.unpack(endian + 'IIII', data[off:off+16])
        except Exception:
            break
        off += 16
        if incl > len(data) - off:
            break
        pkt = data[off:off+incl]
        off += incl
        # Ethernet + IPv4 + UDP/TCP payload extraction (rough)
        if len(pkt) < 14:
            continue
        etype = struct.unpack('>H', pkt[12:14])[0]
        if etype != 0x0800 or len(pkt) < 34:
            continue
        ip = pkt[14:]
        ihl = (ip[0] & 0xF) * 4
        if len(ip) < ihl:
            continue
        proto = ip[9]
        total_len = struct.unpack('>H', ip[2:4])[0]
        trans = ip[ihl: total_len if total_len and total_len <= len(ip) else len(ip)]
        if proto == 17 and len(trans) >= 8:
            dport = struct.unpack('>H', trans[2:4])[0]
            cfg.payloads[65536 + dport] = trans[8:]
        elif proto == 6 and len(trans) >= 20:
            dport = struct.unpack('>H', trans[2:4])[0]
            toff = (trans[12] >> 4) * 4
            if len(trans) > toff:
                # TCP payloads are not used as UDP templates in original, ignore?
                pass
    return

