def _check_adapter_port_bad(orig_name, value):
    # If a plain port number in spec exceeds 65535 (and not I/O), original prints
    # FAIL: bad source port specification: <name>
    # We scan digit runs, taking into account prefixes in tokens.
    # Simple heuristic: if any integer token >65535, fatal with that message.
    s = value
    i = 0
    has_bad = False
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit(): j += 1
            try:
                if int(s[i:j]) > 65535: has_bad = True
            except Exception: pass
            i = j
        else:
            i += 1
    if has_bad:
        eprint(f"FAIL: bad source port specification: {orig_name}")
        raise FatalExit(1)

def set_capture(cfg, value, enable):
