            j = 0
            while j < len(rest) and rest[j].isdigit(): j += 1
            port = int(rest[:j])
    val, nxt = parse_ipv4_token(ip_part, 0)
    if val is None or nxt != len(ip_part):
        eprint(f"FAIL:  bad redis IP address: {value}")
        raise FatalExit(1)
    if port is not None:
        if port < 1 or port > 65535:
            eprint(f"FAIL: bad redis port: {port}")
            raise FatalExit(1)
