        "servername": "servername", "server-name": "servername",
        "heartbleed": "heartbleed", "heart-bleed": "heartbleed",
        "ticketbleed": "ticketbleed", "ticket-bleed": "ticketbleed",
        "html": "html",
    }
    if v not in aliases:
        eprint(f"FAIL: {value}: unknown {kind} type")
        return
    cfg.capture[aliases[v]] = enable

