def ctime_str(epoch):
    # C ctime in local timezone (container UTC), e.g. 'Fri Oct  9 02:49:17 2026'
    try:
        dt = datetime.fromtimestamp(epoch)
    except Exception:
        dt = datetime.fromtimestamp(0)
