class Event:
    __slots__ = ("kind", "timestamp", "ip_version", "ip", "ip_proto", "port", "reason", "ttl", "app_proto", "banner")
    def __init__(self, kind, timestamp, ip_version, ip, ip_proto, port, reason=0, ttl=0, app_proto=0, banner=b""):
        self.kind = kind  # 'open','closed','banner'
        self.timestamp = timestamp
        self.ip_version = ip_version
        self.ip = ip
        self.ip_proto = ip_proto
        self.port = port
        self.reason = reason
        self.ttl = ttl
        self.app_proto = app_proto
        self.banner = banner
    def ip_str(self):
        return format_ip(self.ip_version, self.ip)

class Output:
    def __init__(self, cfg):
        self.cfg = cfg
        self.fp = None
        self.is_stdout = False
        self.opened = False
        self.header_written = False
        self.start_time = None
        self.first_timestamp = None
        self.hosts_up = 0
        self.hosts_down = 0
        self.hosts_total = 0
        self.format = cfg.output_format  # None = console
        self.failed = False

    def open(self):
        """Open output file (create/truncate). Returns True if ok.
        If a format was specified but no filename, print ERR lines and return False.
        Console format uses stdout and always succeeds."""
        cfg = self.cfg
        if self.format is None:
            self.fp = sys.stdout.buffer
            self.is_stdout = True
            self.opened = True
            return True
        fn = cfg.output_filename
        if fn is None:
            eprint("[-] ERR: no output file, use `--output-filename <filename>` to set one")
            eprint("[-] ERR: for `stdout`, use `--output-filename -`")
            self.failed = True
            return False
        if fn == "-":
            self.fp = sys.stdout.buffer
            self.is_stdout = True
            self.opened = True
            return True
        if self.format == "redis":
            # handled specially; keep a dummy fp (BytesIO-like to /dev/null)
            # Connection attempts happen in header writing / emit.
            self.fp = open(os.devnull, "wb")
            self.opened = True
            return True
        mode = "ab" if cfg.output_append else "wb"
        try:
            self.fp = open(fn, mode)
        except OSError as ex:
            # Original message for unwritable output file unknown; approximate.
            eprint(f"[-] {fn}: {ex.strerror or str(ex)}")
            self.failed = True
            return False
        self.opened = True
        return True

    def _write(self, data):
        if self.fp is None:
            return
        if isinstance(data, str):
            data = data.encode('utf-8', errors='ignore')
        try:
            self.fp.write(data)
        except Exception:
            pass

    def _write_header_if_needed(self, ev):
        if self.header_written:
            return
        self.header_written = True
        self.start_time = int(time.time())
        self.first_timestamp = ev.timestamp
        fmt = self.format
        cfg = self.cfg
        if fmt is None:
            return
        if fmt == "list" or fmt == "unicornscan":
            self._write("#masscan\n")
        elif fmt == "xml":
            self._write('<?xml version="1.0"?>\r\n')
            if cfg.stylesheet is not None:
                self._write(f'<?xml-stylesheet href="{cfg.stylesheet}" type="text/xsl"?>\r\n')
            self._write('<!-- masscan v1.0 scan -->\r\n')
            self._write(f'<nmaprun scanner="masscan" start="{self.start_time}" version="1.0-BETA"  xmloutputversion="1.03">\r\n')
            self._write('<scaninfo type="syn" protocol="tcp" />\r\n')
        elif fmt == "json":
            self._write("[\n")
        elif fmt == "ndjson":
            pass
        elif fmt == "grepable":
            self._write(f"# Masscan 1.3.9-integration scan initiated {ctime_str(ev.timestamp)}\n")
            # Ports scanned line based on cfg.ports by proto groups
            self._write(self._grep_ports_line() + "\n")
        elif fmt == "binary":
            # header pseudo-record: 99 bytes: text with s:<first ts>, zero padded
            header_text = f"masscan/1.1\ns:{ev.timestamp}\n".encode()
            chunk = header_text + b"\x00" * (99 - len(header_text))
            self._write(chunk)
        elif fmt == "redis":
            # try connect later per record; keep silent here
            pass

    def _grep_ports_line(self):
        cfg = self.cfg
        # count ports by categories TCP/UDP/SCTP/PROTOCOLS(I)
        counts = {"TCP": 0, "UDP": 0, "SCTP": 0, "PROTOCOLS": 0}
        lists = {"TCP": [], "UDP": [], "SCTP": [], "PROTOCOLS": []}
        for b, e in cfg.ports.ranges:
            # iterate splitting by boundaries; for large ranges this could be heavy,
            # but grep header in original lists ranges condensed e.g. could be ?
            # Observed with no ports: TCP(0;) etc. With ports, likely lists like TCP(1;80)
            cur = b
            while cur <= e:
                if cur < 65536:
                    cat, pe = "TCP", min(e, 65535); pb, pend = cur, pe
                elif cur < 131072:
                    cat, pe = "UDP", min(e, 131071); pb, pend = cur-65536, pe-65536
                elif cur < 196608:
                    cat, pe = "SCTP", min(e, 196607); pb, pend = cur-131072, pe-131072
                else:
                    cat, pe = "PROTOCOLS", e; pb, pend = cur-196608, pe-196608
                counts[cat] += (pe - cur + 1)
                if pb == pend: lists[cat].append(str(pb))
                else: lists[cat].append(f"{pb}-{pend}")
                cur = pe + 1
        parts = []
        for cat in ["TCP", "UDP", "SCTP", "PROTOCOLS"]:
            lst = ",".join(lists[cat])
