        if fmt == "list" or fmt == "unicornscan":
            self._write("#masscan\n")
        elif fmt == "xml":
            self._write('<?xml version="1.0"?>\r\n')
            if cfg.stylesheet is not None:
                self._write(f'<?xml-stylesheet href="{cfg.stylesheet}" type="text/xsl"?>\r\n')
            self._write('<!-- masscan v1.0 scan -->\r\n')
            self._write(f'<nmaprun scanner="masscan" start="{self.start_time}" version="1.0-BETA"  xmloutputversion="1.03">\r\n')
            self._write('<scaninfo type="syn" protocol="tcp" />\r\n')
        elif fmt == "json":
            self._write("[\n")
        elif fmt == "ndjson":
            pass
        elif fmt == "grepable":
