            # Ports scanned line based on cfg.ports by proto groups
            self._write(self._grep_ports_line() + "\n")
        elif fmt == "binary":
            # header pseudo-record: 99 bytes: text with s:<first ts>, zero padded
            header_text = f"masscan/1.1\ns:{ev.timestamp}\n".encode()
            chunk = header_text + b"\x00" * (99 - len(header_text))
            self._write(chunk)
