                self._write(f"Timestamp: {ev.timestamp}\tHost: {ip_s} ()\tPorts: {ev.port}/{ev.kind}/{proto}//{svc}//\n")
            elif ev.kind == "banner":
                self._write(f"Host: {ip_s} ()\tPort: {ev.port}\tService: {app_name(ev.app_proto)}\tBanner: {escape_banner_text(ev.banner)}\n")
        elif fmt == "binary":
            self._write_binary_event(ev)
        elif fmt == "redis":
            self._write_redis_event(ev)

    def _write_binary_event(self, ev):
        # Canonical record types:
        # IPv4 status: type 6 open / 7 closed (len13)
        # IPv4 banner: type 9 (len 14+banner)
        # IPv6 status: type 10 open / 11 closed (len26)
        # IPv6 banner: type 13 (len 27+banner)
        def varint(n):
            if n == 0:
                return b"\x00"
            parts = []
            while n > 0:
                parts.append(n & 0x7f); n >>= 7
            parts.reverse()
            out = bytearray()
            for idx, p in enumerate(parts):
                out.append(p | (0x80 if idx < len(parts)-1 else 0))
            return bytes(out)
        if ev.ip_version == 4:
            if ev.kind in ("open", "closed"):
                t = 6 if ev.kind == "open" else 7
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + struct.pack('>I', ev.ip) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + bytes([ev.reason & 0xFF, ev.ttl & 0xFF])
                self._write(varint(t) + varint(len(data)) + data)
            elif ev.kind == "banner":
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + struct.pack('>I', ev.ip) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + struct.pack('>H', ev.app_proto & 0xFFFF) + bytes([ev.ttl & 0xFF]) + ev.banner
                self._write(varint(9) + varint(len(data)) + data)
        else:
            if ev.kind in ("open", "closed"):
                t = 10 if ev.kind == "open" else 11
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + bytes([ev.reason & 0xFF, ev.ttl & 0xFF, 6]) + ev.ip.to_bytes(16, 'big')
                self._write(varint(t) + varint(len(data)) + data)
            elif ev.kind == "banner":
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + struct.pack('>H', ev.app_proto & 0xFFFF) + bytes([ev.ttl & 0xFF, 6]) + ev.ip.to_bytes(16, 'big') + ev.banner
                self._write(varint(13) + varint(len(data)) + data)

    def _write_redis_event(self, ev):
        # Best effort: try to connect once and send a simple command; failures ignored
        # Original likely prints errors on connect fail; not yet probed in depth.
        try:
            if getattr(self, "_redis_sock", None) is None:
                s = socket.create_connection((self.cfg.redis_ip, self.cfg.redis_port), timeout=2)
                self._redis_sock = s
            # A simple representation; exact protocol unknown
            msg = f"{ev.kind} {ev.ip_str()} {ev.port}\n".encode()
            self._redis_sock.sendall(msg)
        except Exception:
            pass

    def close(self):
        if not self.opened:
            return
        if self.header_written:
            fmt = self.format
            if fmt == "list" or fmt == "unicornscan":
                self._write("# end\n")
            elif fmt == "xml":
                finish = int(time.time())
                elapsed = finish - (self.start_time or finish)
                timestr = datetime.fromtimestamp(finish).strftime("%Y-%m-%d %H:%M:%S")
                self._write("<runstats>\r\n")
                self._write(f'<finished time="{finish}" timestr="{timestr}" elapsed="{elapsed}" />\r\n')
                self._write(f'<hosts up="{self.hosts_up}" down="{self.hosts_down}" total="{self.hosts_total}" />\r\n')
                self._write("</runstats>\r\n")
                self._write("</nmaprun>\r\n")
            elif fmt == "json":
                self._write("]\n")
            elif fmt == "grepable":
                self._write(f"# Masscan done at {ctime_str(int(time.time()))}\n")
            elif fmt == "binary":
                chunk = b"masscan/1.1" + b"\x00" * (99 - len(b"masscan/1.1"))
                self._write(chunk)
            # ndjson, console, redis: nothing
        try:
            if self.fp and not self.is_stdout:
                self.fp.close()
            elif self.fp:
                self.fp.flush()
        except Exception:
            pass

