    out = []
    for b in data:
        if b < 0x20 or b >= 0x7f or b in (0x22, 0x26, 0x27, 0x3c, 0x3e, 0x5c):
            out.append(f"\\x{b:02x}")
        else:
            out.append(chr(b))
    return "".join(out)

