                    cat, pe = "SCTP", min(e, 196607); pb, pend = cur-131072, pe-131072
                else:
                    cat, pe = "PROTOCOLS", e; pb, pend = cur-196608, pe-196608
                counts[cat] += (pe - cur + 1)
                if pb == pend: lists[cat].append(str(pb))
                else: lists[cat].append(f"{pb}-{pend}")
                cur = pe + 1
        parts = []
        for cat in ["TCP", "UDP", "SCTP", "PROTOCOLS"]:
            lst = ",".join(lists[cat])
            parts.append(f"{cat}({counts[cat]};{lst})")
        return "# Ports scanned: " + " ".join(parts)

    def should_emit(self, ev):
        cfg = self.cfg
        if ev.kind == "closed" and not cfg.output_status_closed:
            return False
        if ev.kind == "open" and not cfg.output_status_open:
            return False
        if ev.kind == "banner":
            if not cfg.is_banners:
                return False
            if cfg.banner_types_mask:
                if ev.app_proto >= 64 or not (cfg.banner_types_mask >> ev.app_proto) & 1:
                    return False
        return True

    def emit(self, ev):
        if not self.opened or self.failed:
            return
        if not self.should_emit(ev):
            return
        self._write_header_if_needed(ev)
        fmt = self.format
        ip_s = ev.ip_str()
        proto = proto_name(ev.ip_proto)
        if fmt is None:
            if ev.kind in ("open", "closed"):
                s = f"Discovered {ev.kind} port {ev.port}/{proto} on {ip_s}"
                # padded to 79 chars if shorter
                if len(s) < 79:
                    s = s + " " * (79 - len(s))
                self._write(s + "\n")
            elif ev.kind == "banner":
                self._write(f"Banner on port {ev.port}/{proto} on {ip_s}: [{app_name(ev.app_proto)}] {escape_banner_text(ev.banner)}\n")
            return
        if fmt == "list":
            if ev.kind in ("open", "closed"):
                self._write(f"{ev.kind} {proto} {ev.port} {ip_s} {ev.timestamp}\n")
            elif ev.kind == "banner":
                self._write(f"banner {proto} {ev.port} {ip_s} {ev.timestamp} {app_name(ev.app_proto)} {escape_banner_text(ev.banner)}\n")
        elif fmt == "unicornscan":
            # Observed: banner records produce no lines; status format probed later,
            # implement template similar to list for statuses as fallback.
            if ev.kind in ("open", "closed"):
                # This format is patched after probing (see notes); temporary:
                self._write(f"{ev.kind} {proto} {ev.port} {ip_s} {ev.timestamp}\n")
        elif fmt == "xml":
            if ev.kind in ("open", "closed"):
                reason = reason_string(ev.reason)
                # host counting: observed type1 TCP open counted up/total; others?
                # Count open/tcp as up, closed/tcp as down? refine via probes.
                if ev.ip_proto == 6:
                    if ev.kind == "open":
                        self.hosts_up += 1; self.hosts_total += 1
                    elif ev.kind == "closed":
                        self.hosts_down += 1; self.hosts_total += 1
                self._write(f'<host endtime="{ev.timestamp}"><address addr="{ip_s}" addrtype="ipv4"/><ports><port protocol="{proto}" portid="{ev.port}"><state state="{ev.kind}" reason="{reason}" reason_ttl="{ev.ttl}"/></port></ports></host>\r\n')
            elif ev.kind == "banner":
                self._write(f'<host endtime="{ev.timestamp}"><address addr="{ip_s}" addrtype="ipv4"/><ports><port protocol="{proto}" portid="{ev.port}"><state state="open" reason="response" reason_ttl="{ev.ttl}" /><service name="{app_name(ev.app_proto)}" banner="{escape_banner_text(ev.banner)}"></service></port></ports></host>\r\n')
        elif fmt == "json":
            if ev.kind in ("open", "closed"):
                self._write('{   "ip": "%s",   "timestamp": "%s", "ports": [ {"port": %d, "proto": "%s", "status": "%s", "reason": "%s", "ttl": %d} ] }\n' % (ip_s, ev.timestamp, ev.port, proto, ev.kind, reason_string(ev.reason), ev.ttl))
            elif ev.kind == "banner":
                self._write('{   "ip": "%s",   "timestamp": "%s", "ports": [ {"port": %d, "proto": "%s", "service": {"name": "%s", "banner": "%s"} } ] }\n' % (ip_s, ev.timestamp, ev.port, proto, app_name(ev.app_proto), escape_banner_json(ev.banner)))
        elif fmt == "ndjson":
            if ev.kind in ("open", "closed"):
                self._write('{"ip":"%s","timestamp":"%s","port":%d,"proto":"%s","rec_type":"status","data":{"status":"%s","reason":"%s","ttl":%d}}\n' % (ip_s, ev.timestamp, ev.port, proto, ev.kind, reason_string(ev.reason), ev.ttl))
            elif ev.kind == "banner":
                self._write('{"ip":"%s","timestamp":"%s","port":%d,"proto":"%s","rec_type":"banner","data":{"service_name":"%s","banner":"%s"}}\n' % (ip_s, ev.timestamp, ev.port, proto, app_name(ev.app_proto), escape_banner_json(ev.banner)))
        elif fmt == "grepable":
            if ev.kind in ("open", "closed"):
                # service field
                if ev.ip_proto in (6, 17, 132):
                    svc = PORT_SERVICES.get(ev.port, "unknown")
                else:
                    svc = IP_PROTOCOL_SERVICE_NAMES.get(ev.ip_proto, "unknown")
                self._write(f"Timestamp: {ev.timestamp}\tHost: {ip_s} ()\tPorts: {ev.port}/{ev.kind}/{proto}//{svc}//\n")
            elif ev.kind == "banner":
                self._write(f"Host: {ip_s} ()\tPort: {ev.port}\tService: {app_name(ev.app_proto)}\tBanner: {escape_banner_text(ev.banner)}\n")
        elif fmt == "binary":
            self._write_binary_event(ev)
        elif fmt == "redis":
            self._write_redis_event(ev)

    def _write_binary_event(self, ev):
        # Canonical record types:
        # IPv4 status: type 6 open / 7 closed (len13)
        # IPv4 banner: type 9 (len 14+banner)
        # IPv6 status: type 10 open / 11 closed (len26)
        # IPv6 banner: type 13 (len 27+banner)
        def varint(n):
            if n == 0:
                return b"\x00"
            parts = []
            while n > 0:
                parts.append(n & 0x7f); n >>= 7
            parts.reverse()
            out = bytearray()
            for idx, p in enumerate(parts):
                out.append(p | (0x80 if idx < len(parts)-1 else 0))
            return bytes(out)
        if ev.ip_version == 4:
            if ev.kind in ("open", "closed"):
                t = 6 if ev.kind == "open" else 7
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + struct.pack('>I', ev.ip) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + bytes([ev.reason & 0xFF, ev.ttl & 0xFF])
                self._write(varint(t) + varint(len(data)) + data)
            elif ev.kind == "banner":
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + struct.pack('>I', ev.ip) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + struct.pack('>H', ev.app_proto & 0xFFFF) + bytes([ev.ttl & 0xFF]) + ev.banner
                self._write(varint(9) + varint(len(data)) + data)
        else:
            if ev.kind in ("open", "closed"):
                t = 10 if ev.kind == "open" else 11
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + bytes([ev.reason & 0xFF, ev.ttl & 0xFF, 6]) + ev.ip.to_bytes(16, 'big')
                self._write(varint(t) + varint(len(data)) + data)
            elif ev.kind == "banner":
                data = struct.pack('>I', ev.timestamp & 0xFFFFFFFF) + bytes([ev.ip_proto & 0xFF]) + struct.pack('>H', ev.port & 0xFFFF) + struct.pack('>H', ev.app_proto & 0xFFFF) + bytes([ev.ttl & 0xFF, 6]) + ev.ip.to_bytes(16, 'big') + ev.banner
                self._write(varint(13) + varint(len(data)) + data)

    def _write_redis_event(self, ev):
        # Best effort: try to connect once and send a simple command; failures ignored
        # Original likely prints errors on connect fail; not yet probed in depth.
        try:
            if getattr(self, "_redis_sock", None) is None:
                s = socket.create_connection((self.cfg.redis_ip, self.cfg.redis_port), timeout=2)
                self._redis_sock = s
            # A simple representation; exact protocol unknown
            msg = f"{ev.kind} {ev.ip_str()} {ev.port}\n".encode()
            self._redis_sock.sendall(msg)
        except Exception:
            pass

    def close(self):
        if not self.opened:
            return
        if self.header_written:
            fmt = self.format
            if fmt == "list" or fmt == "unicornscan":
                self._write("# end\n")
            elif fmt == "xml":
                finish = int(time.time())
                elapsed = finish - (self.start_time or finish)
                timestr = datetime.fromtimestamp(finish).strftime("%Y-%m-%d %H:%M:%S")
                self._write("<runstats>\r\n")
                self._write(f'<finished time="{finish}" timestr="{timestr}" elapsed="{elapsed}" />\r\n')
                self._write(f'<hosts up="{self.hosts_up}" down="{self.hosts_down}" total="{self.hosts_total}" />\r\n')
                self._write("</runstats>\r\n")
                self._write("</nmaprun>\r\n")
            elif fmt == "json":
                self._write("]\n")
            elif fmt == "grepable":
                self._write(f"# Masscan done at {ctime_str(int(time.time()))}\n")
            elif fmt == "binary":
                chunk = b"masscan/1.1" + b"\x00" * (99 - len(b"masscan/1.1"))
                self._write(chunk)
            # ndjson, console, redis: nothing
        try:
            if self.fp and not self.is_stdout:
                self.fp.close()
            elif self.fp:
                self.fp.flush()
        except Exception:
            pass

PY
