            'C': "nmap(-sC): unsupported",
            'F': "nmap(-sF): FIN scan not yet supported",
            'I': "nmap(-sI): Zombie scans will never be supported",
            'M': "nmap(-sM): Maimon scan not yet supported",
            'N': "nmap(-sN): NULL scan not yet supported",
            'P': "nmap(-sP): unsupported option",
            'V': "nmap(-sV): unlikely this will be supported",
            'W': "nmap(-sW): Windows scan not yet supported",
            'X': "nmap(-sX): Xmas scan not yet supported",
            'n': "nmap(-sn): ping-sweeps not yet supported",
