import subprocess,ipaddress
def perm(seed,N):
    end=str(ipaddress.IPv4Address(N-1)); p=subprocess.run(["./executable","-sL","--seed",str(seed),f"0.0.0.0-{end}"],capture_output=True,text=True,timeout=5); return [int(ipaddress.IPv4Address(x)) for x in p.stdout.splitlines()]
def find(P):
    N=len(P); sols=[]
    for M in range(N,500):
        for A in range(1,M):
            if __import__('math').gcd(A,M)!=1: continue
            B=P[0]  # if P0 is cyclewalk result, not necessarily enc(0)=B if B>=N, so this assumption may miss
            # Instead try all B that give cyclewalk(0)=P0: iterate y=B, while y>=N y=(y+A)%M, eventually must equal P0 and not cycle forever
            for B in range(M):
                out=[]
                ok=True
                for x in range(N):
                    y=(A*x+B)%M; steps=0
                    while y>=N:
                        y=(A*y+B)%M; steps+=1
                        if steps>1000: ok=False; break
                    if not ok: break
                    out.append(y)
                if ok and out==P: sols.append((M,A,B))
        if sols: return sols
    return sols
for N in [16,36,100]:
    for seed in [1,42]:
        print(N,seed,find(perm(seed,N))[:5])
