import subprocess, ipaddress, math, collections, sys
def perm(seed,N,r):
    end=str(ipaddress.IPv4Address(N-1)); p=subprocess.run(["./executable","-sL","--seed",str(seed),f"--blackrock-rounds={r}",f"0.0.0.0-{end}"],capture_output=True,text=True,timeout=5); return [int(ipaddress.IPv4Address(x)) for x in p.stdout.splitlines()]
def extract(N,seed,maxrounds=14):
    A=int(math.isqrt(N))-2
    if A<1: A=1
    B=N//A+1
    M=A*B
    print(f"N={N} A={A} B={B} M={M} seed={seed}")
    E=list(range(M)) # E0
    Fs=[]
    for r in range(1,maxrounds+1):
        P=perm(seed,N,r)
        # determine grouping and offset candidates via direct matches
        if r%2==1:
            groups={v:collections.Counter() for v in range(B)}
            for x in range(N):
                yprev=E[x]; u=yprev%A; v=yprev//A
                yobs=P[x]
                if yobs//A != v: continue # not direct (cycle or model wrong)
                offset=(yobs%A - u)%A
                groups[v][offset]+=1
            f=[]
            for v in range(B):
                if groups[v]: f.append(groups[v].most_common(1)[0][0])
                else: f.append(0)
            # construct Er
            Er=[]
            for z in range(M):
                yprev=E[z]; u=yprev%A; v=yprev//A; Er.append(v*A+((u+f[v])%A))
        else:
            groups={u:collections.Counter() for u in range(A)}
            for x in range(N):
                yprev=E[x]; u=yprev%A; v=yprev//A; yobs=P[x]
                if yobs%A != u: continue
                offset=(yobs//A - v)%B
                groups[u][offset]+=1
            f=[]
            for u in range(A):
                if groups[u]: f.append(groups[u].most_common(1)[0][0])
                else: f.append(0)
            Er=[]
            for z in range(M):
                yprev=E[z]; u=yprev%A; v=yprev//A; Er.append(((v+f[u])%B)*A+u)
        # predict cyclewalk
        pred=[]
        for x in range(N):
            y=Er[x]; steps=0
            while y>=N and steps<1000:
                y=Er[y]; steps+=1
            pred.append(y)
        matches=sum(1 for a,b in zip(pred,P) if a==b)
        print(f" round {r}: f={f} pred matches {matches}/{N}")
        if matches!=N:
            # print first mismatches
            print("  mismatches",[(i,P[i],pred[i]) for i in range(N) if P[i]!=pred[i]][:20])
        Fs.append(f); E=Er
    return Fs,E
if __name__=="__main__":
    N=int(sys.argv[1]) if len(sys.argv)>1 else 103
    seed=int(sys.argv[2]) if len(sys.argv)>2 else 42
    extract(N,seed,14)
