import subprocess,ipaddress,math
def perm(seed,N,r):
    end=str(ipaddress.IPv4Address(N-1)); p=subprocess.run(["./executable","-sL","--seed",str(seed),f"--blackrock-rounds={r}",f"0.0.0.0-{end}"],capture_output=True,text=True,timeout=5); return [int(ipaddress.IPv4Address(x)) for x in p.stdout.splitlines()]
# Choose one N for each A>=2: choose smallest N with isqrt(N)-2=A => N=(A+2)^2 . B=N//A+1
def f_table(seed,A):
    N=(A+2)*(A+2)
    P=perm(seed,N,1); B=N//A+1; f=[]
    for v in range(B):
        vals=set()
        for u in range(A):
            x=v*A+u
            if x<N and P[x]//A==v: vals.add((P[x]%A-u)%A)
        f.append(vals)
    return f,B
seed=42
tables={}
for A in range(2,41):
    f,B=f_table(seed,A); tables[A]=(f,B); print("A",A,"B",B,"f",[list(x)[0] if len(x)==1 else x for x in f])
# CRT solver incremental
def crt(conds):
    # returns smallest >=0 solution and modulus, or None
    x=0; M=1
    for a,r in conds:
        # solve x + M*t = r mod a
        import math
        g=math.gcd(M,a)
        if (r-x)%g: return None
        # brute t in range a/g
        for t in range(a//g+1):
            if (x+M*t)%a==r:
                x=x+M*t; M=M//g*a; break
    return x,M
for v in range(0,10):
    conds=[]
    for A in range(2,41):
        f,B=tables[A]
        if v<B and len(f[v])==1: conds.append((A,list(f[v])[0]))
    print("v",v,crt(conds),conds)
