import subprocess,ipaddress,math,collections
def perm(seed,N,r):
    end=str(ipaddress.IPv4Address(N-1)); p=subprocess.run(["./executable","-sL","--seed",str(seed),f"--blackrock-rounds={r}",f"0.0.0.0-{end}"],capture_output=True,text=True,timeout=10); return [int(ipaddress.IPv4Address(x)) for x in p.stdout.splitlines()]
def tables(N,seed,maxr):
    A=int(math.isqrt(N))-2; B=N//A+1; M=A*B; E=list(range(M)); Fs=[]
    for r in range(1,maxr+1):
        P=perm(seed,N,r)
        if r%2==1:
            groups={v:collections.Counter() for v in range(B)}
            for x in range(N):
                y=E[x]; u=y%A; v=y//A
                if P[x]//A==v: groups[v][(P[x]%A-u)%A]+=1
            f=[groups[v].most_common(1)[0][0] if groups[v] else 0 for v in range(B)]
            E=[(E[z]//A)*A+((E[z]%A+f[E[z]//A])%A) for z in range(M)]
        else:
            groups={u:collections.Counter() for u in range(A)}
            for x in range(N):
                y=E[x]; u=y%A; v=y//A
                if P[x]%A==u: groups[u][(P[x]//A-v)%B]+=1
            f=[groups[u].most_common(1)[0][0] if groups[u] else 0 for u in range(A)]
            E=[((E[z]//A+f[E[z]%A])%B)*A+(E[z]%A) for z in range(M)]
        Fs.append(f)
    return A,B,Fs
def crt(conds):
    x=0;M=1
    for a,r in conds:
