targets={0:10778240244945439410,1:10778240244945439237,2:10778240244945439391,3:10778240244945439348}
seed=42;j=1
def enc(val,kind):
    if kind=="u8": return bytes([val&255])
    if kind=="u16le": return struct.pack('<H',val&65535)
    if kind=="u16be": return struct.pack('>H',val&65535)
    if kind=="u32le": return struct.pack('<I',val&0xFFFFFFFF)
    if kind=="u32be": return struct.pack('>I',val&0xFFFFFFFF)
    if kind=="u64le": return struct.pack('<Q',val&MASK)
    if kind=="u64be": return struct.pack('>Q',val&MASK)
    if kind=="dec": return str(val).encode()
    if kind=="hex": return format(val,'x').encode()
    raise ValueError
