    out={}
    h=14695981039346656037
    for b in data: h=((h*1099511628211)&MASK)^b
    out["fnv1"]=h
    h=14695981039346656037
    for b in data: h=((h^b)*1099511628211)&MASK
    out["fnv1a"]=h
    h=5381
    for b in data: h=((h*33)+b)&MASK
    out["djb_add"]=h
    h=5381
    for b in data: h=((h*33)^b)&MASK
    out["djb_xor"]=h
    h=0
    for b in data: h=(b+(h<<6)+(h<<16)-h)&MASK
    out["sdbm"]=h
    h=0
    for b in data:
        h=(h+b)&MASK; h=(h+(h<<10))&MASK; h^=(h>>6)
    out["jenkins_no_final"]=h
    hh=h; hh=(hh+(hh<<3))&MASK; hh^=(hh>>11); hh=(hh+(hh<<15))&MASK; out["jenkins_final"]=hh
    # polynomial multipliers
    for mult in [33,37,39,131,257,65599,31,16777619]:
        h=0
        for b in data: h=(h*mult+b)&MASK
        out[f"poly{mult}_add"]=h
        h=0
        for b in data: h=((h*mult)^b)&MASK
        out[f"poly{mult}_xor"]=h
        h=14695981039346656037 if mult==1099511628211 else 0
    return out
kinds=["u8","u16le","u16be","u32le","u32be","u64le","u64be","dec","hex"]
components=["seed","round","R"]
best=[]
# orders permutations of components, and encoding per component can vary by type of value? Limit: use same kind for all numeric components first, plus mixed selected
for order in itertools.permutations(components):
    for kind in kinds:
        # build candidate function
        def build(R):
            vals={"seed":seed,"round":j,"R":R}; return b"".join(enc(vals[c],kind) for c in order)
        cands0=hashes(build(0))
        for hn,hv in cands0.items():
            if hv==targets[0]: print("EXACT MATCH",order,kind,hn)
            # score low byte / high match across R
            score=0
            for R,t in targets.items():
                if hashes(build(R))[hn]==t: score+=1
            if score: best.append((score,order,kind,hn))
print("best exact score",sorted(best,reverse=True)[:10])
# also mixed: seed 64le, round u8/u32, R u8 last variants manually via all kind combos
best=[]
for order in itertools.permutations(components):
 for ks in kinds:
  for kj in ["u8","u32le","u64le","dec"]:
   for kr in ["u8","u16le","u32le","u64le","dec"]:
    kindmap={"seed":ks,"round":kj,"R":kr}
    def build(R):
        vals={"seed":seed,"round":j,"R":R}; return b"".join(enc(vals[c],kindmap[c]) for c in order)
    cands0=hashes(build(0))
    for hn,hv in cands0.items():
        if hv==targets[0]: print("MIXED MATCH",order,kindmap,hn)
print("done")
