import subprocess,collections
def perm(seed,N,r):
    p=subprocess.run(["./executable","-sL","--seed",str(seed),f"--blackrock-rounds={r}",f"10.0.0.0-10.0.0.{N-1}"],capture_output=True,text=True,timeout=5); return [int(x.split(".")[-1]) for x in p.stdout.splitlines()]
Amap={2:1,3:1,4:2,5:2,6:2,7:3,8:3}
for N,A in Amap.items():
    print("N",N,"A",A)
    for B in range(1,15):
        score=0; denom=0
        for seed in [1,2,42,999]:
            P1=perm(seed,N,1); P2=perm(seed,N,2)
            groups={}
            for x in range(N):
                if P2[x]%A!=P1[x]%A: continue
                denom+=1; u=P1[x]%A; delta=(P2[x]//A-P1[x]//A)%B
                groups.setdefault(u,collections.Counter())[delta]+=1
            score+=sum(max(c.values()) for c in groups.values())
        print(" B",B,score,"/",denom)
