import hashlib, struct, binascii, zlib
target=10778240244945439410
seed=42;j=1
def check(name,val):
    if (val>>8)==(target>>8): print("HIGH MATCH",name,hex(val))
    if val==target: print("EXACT MATCH",name)
# MD5/SHA etc of various data layouts, take first 8 bytes LE/BE
datas={}
for fmt in ['<Q','>Q','<I','>I','<QII','>QII','<IIQ','<QQ','<II','<QII']:
    try: datas[fmt]=struct.pack(fmt,seed,j) if fmt.count('Q')+fmt.count('I')==2 else struct.pack(fmt,seed)
    except Exception: pass
datas["seedstr"]=b"42"; datas["seedjstr"]=b"42:1"; datas["bytes [42,1]"]=bytes([42,1]); datas["empty"]=b""
for dn,data in datas.items():
    for algo in ["md5","sha1","sha256","sha512","blake2b","blake2s"]:
        h=hashlib.new(algo,data).digest()
        for endian in ['<','>']:
            v=struct.unpack(endian+'Q',h[:8])[0]; check(f"{algo} {dn} {endian}first8",v)
            v=struct.unpack(endian+'Q',h[-8:])[0]; check(f"{algo} {dn} {endian}last8",v)
    check(f"crc32 {dn}", binascii.crc32(data)&0xffffffff)
# SipHash with various keys/inputs: load sip
src=open("/tmp/hashsearch.py").read(); exec(src.split("# verify siphash")[0],globals())
for kname,k0,k1 in [("0,0",0,0),("seed,0",seed,0),("0,seed",0,seed),("seed,seed",seed,seed),("seed,j",seed,j),("j,seed",j,seed)]:
    for dn,data in datas.items():
        check(f"sip {dn} {kname}",siphash(data,k0,k1))
print("done target",hex(target))
